import {esc} from './organiser-utils.js';
export const overdue=(assignment,stage,now=Date.now())=>!['selected','not_selected'].includes(stage)&&!!assignment?.due_at&&Date.parse(assignment.due_at)<now;
export async function teamReview(host,sb,id,isCurrent,onAssignment){
 host.innerHTML='<p role="status">Loading review tools…</p>';
 try{
 const [team,a,c,user]=await Promise.all([sb.rpc('elan_review_team'),sb.from('elan_review_assignments').select('*').eq('enquiry_id',id).maybeSingle(),sb.from('elan_review_scorecards').select('*').eq('enquiry_id',id),sb.auth.getUser()]);
 if(!isCurrent())return;
 for(const r of [team,a,c,user])if(r.error)throw r.error;
 const uid=user.data.user.id;let assignment=a.data,own=c.data.find(x=>x.reviewer_id===uid);
 const label=id=>team.data.find(t=>t.id===id)?.label||'Former reviewer';
 const criteria=[['fit','Department fit','Relevant experience or clear evidence of ability to learn.'],['communication','Communication','Clear answers, listening and constructive discussion.'],['reliability','Reliability','Realistic availability and evidence of following through.'],['initiative','Initiative','Practical ideas and willingness to take responsibility.']];
 host.innerHTML=`<section class="team-review"><h3>Review ownership</h3><p>Internal only. Assign responsibility and a follow-up deadline.</p><form data-extra="assignment"><label>Review owner<select name="owner"><option value="">Unassigned</option>${team.data.map(t=>`<option value="${esc(t.id)}" ${assignment?.owner_id===t.id?'selected':''}>${esc(t.label)} · ${esc(t.role)}</option>`).join('')}</select></label><label>Review due (your local time)<input type="datetime-local" name="due"></label><button>Save assignment</button><p role="status"></p></form><h3>Your interview scorecard</h3><p>1 = limited evidence · 3 = meets expectations · 5 = strong evidence. Use examples from the application or interview. Scores support discussion; they do not automatically select anyone.</p><form data-extra="scorecard"><div class="score-grid">${criteria.map(([key,title,help])=>`<label>${title}<small>${help}</small><select name="${key}" required><option value="">Choose score</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${own?.[key]===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><label>Evidence and interview notes<textarea name="evidence" rows="4" maxlength="4000" required>${esc(own?.evidence||'')}</textarea></label><label>Recommendation<select name="recommendation" required><option value="">Choose recommendation</option>${['Proceed','Discuss','Do not proceed'].map(x=>`<option ${own?.recommendation===x?'selected':''}>${x}</option>`).join('')}</select></label><button>Save my scorecard</button><p role="status"></p></form><details><summary>Team scorecards (${c.data.length})</summary><div data-cards></div></details></section>`;
 const render=()=>{host.querySelector('[data-cards]').innerHTML=c.data.map(x=>`<article class="score-summary"><h4>${esc(label(x.reviewer_id))}</h4><p>${criteria.map(([key,title])=>`${title}: ${x[key]}/5`).join(' · ')}</p><strong>${esc(x.recommendation)}</strong><p class="preserve-lines">${esc(x.evidence)}</p><small>Updated ${esc(new Date(x.updated_at).toLocaleString())}</small></article>`).join('')||'<p>No scorecards saved yet.</p>';host.querySelector('summary').textContent=`Team scorecards (${c.data.length})`;};render();
 const f=host.querySelector('[data-extra="assignment"]');if(assignment?.due_at){const d=new Date(assignment.due_at);f.elements.due.value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
 for(const form of host.querySelectorAll('form')){form.oninput=()=>form.dataset.dirty='true';form.onsubmit=async e=>{e.preventDefault();if(form.inert||!form.reportValidity())return;form.inert=true;const out=form.querySelector('[role=status]');try{const v=Object.fromEntries(new FormData(form));const isAssignment=form===f;const r=isAssignment?await sb.rpc('elan_save_review_assignment',{p_id:id,p_owner:v.owner||null,p_due:v.due?new Date(v.due).toISOString():null,p_expected:assignment?.version||0}):await sb.rpc('elan_save_review_scorecard',{p_id:id,p_fit:+v.fit,p_communication:+v.communication,p_reliability:+v.reliability,p_initiative:+v.initiative,p_evidence:v.evidence.trim(),p_recommendation:v.recommendation,p_expected:own?.version||0});if(r.error)throw r.error;const data=Array.isArray(r.data)?r.data[0]:r.data;if(isAssignment){assignment=data;onAssignment(data);}else{own=data;const index=c.data.findIndex(x=>x.reviewer_id===uid);if(index<0)c.data.push(data);else c.data[index]=data;render();}form.dataset.dirty='false';out.textContent='Saved. Internal only; no applicant email was sent.';}catch(err){out.textContent=err.message;}finally{form.inert=false;}};}
 }catch(err){if(isCurrent())host.textContent='Review tools could not load: '+err.message;}
}
